examples:
TypeScript streaming resume example:
import { RedwoodClient, StreamCheckpoint } from '@redwood/sdk'
const client = new RedwoodClient({retryProfile: 'latency-optimized'})
const checkpoint = await client.streamChat({conversationId}).checkpoint()
// persist checkpoint to local storage and later resume
await client.streamChat.resume(checkpoint.token)

Go chunked upload example:
uploader := client.NewUploader(WithRetryProfile("throughput-optimized"))
for i, chunk := range chunks {
    dedup := fmt.Sprintf("%s:%d", uploadID, i)
    uploader.UploadChunk(ctx, chunk, DedupKey(dedup))
}
// server will dedupe repeated chunk uploads by dedup key
